/* Demo agenda: one trainer, explicit local availability, capacity one per slot.
   Production requires authenticated APIs and a transactional booking constraint. */
const AGENDA_KEY='forma-agenda-v1';
const AGENDA_SERVICES={training:{name:'Personal training',duration:60},checkup:{name:'Check-up e valutazione',duration:45},consult:{name:'Consulenza programmazione',duration:30}};
function agendaNow(date=new Date()) {const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date);const p=Object.fromEntries(parts.map(v=>[v.type,v.value]));return {date:`${p.year}-${p.month}-${p.day}`,minute:Number(p.hour)*60+Number(p.minute)};}
function agendaAddDays(key,days){const d=new Date(key+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10);}
function agendaTime(minute){return String(Math.floor(minute/60)).padStart(2,'0')+':'+String(minute%60).padStart(2,'0');}
function agendaDateLabel(date,long=false){return new Intl.DateTimeFormat('it-IT',{timeZone:'UTC',weekday:long?'long':'short',day:'numeric',month:'long',...(long?{year:'numeric'}:{})}).format(new Date(date+'T12:00:00Z'));}
function agendaIsFuture(slot,now=agendaNow()){return slot.date>now.date||(slot.date===now.date&&slot.start>now.minute);}
function agendaOverlap(a,b){return a.date===b.date&&a.start<b.start+b.duration&&b.start<a.start+a.duration;}
function agendaReservationFor(data,slotId){return data.reservations.find(r=>r.slotId===slotId&&r.status==='confirmed');}
function agendaLoad(){try{const saved=JSON.parse(localStorage.getItem(AGENDA_KEY));if(saved&&Array.isArray(saved.slots)&&Array.isArray(saved.reservations))return saved;}catch{}return null;}
function agendaSeed(){const today=agendaNow().date,slots=[];for(let offset=1;offset<=7;offset++){const date=agendaAddDays(today,offset),weekday=new Date(date+'T12:00:00Z').getUTCDay();if(weekday===0)continue;for(const [n,start] of [9*60,10*60,15*60].entries()){const service=n===2?'checkup':'training';slots.push({id:'demo-'+date+'-'+start,date,start,duration:AGENDA_SERVICES[service].duration,service,mode:n===1?'Online':'In presenza · Studio Forma',withdrawn:false});}}return {version:1,slots,reservations:[]};}
let agendaData=agendaLoad()||agendaSeed();
try{if(!localStorage.getItem(AGENDA_KEY))localStorage.setItem(AGENDA_KEY,JSON.stringify(agendaData));}catch{}
let agendaSelected=agendaNow().date,agendaMonth=agendaSelected.slice(0,7),agendaFilter='';
function agendaRefresh(){const fresh=agendaLoad();if(fresh)agendaData=fresh;}
function agendaSave(next){try{localStorage.setItem(AGENDA_KEY,JSON.stringify(next));agendaData=next;return true;}catch{toast('Impossibile salvare l’agenda sul dispositivo.');return false;}}
function requireDemoRole(expected){if(role!==expected){toast(expected==='coach'?'Questa funzione è riservata alla vista preparatore.':'Questa funzione è riservata alla vista atleta.');return false;}return true;}
function agendaSlotsFor(date,filter=agendaFilter){return agendaData.slots.filter(s=>s.date===date&&!s.withdrawn&&(!filter||s.service===filter)).sort((a,b)=>a.start-b.start);}
function agendaAvailableSlots(){return agendaData.slots.filter(s=>!s.withdrawn&&agendaIsFuture(s)&&!agendaReservationFor(agendaData,s.id)&&(!agendaFilter||s.service===agendaFilter)).sort((a,b)=>a.date.localeCompare(b.date)||a.start-b.start);}
function agendaSelectDate(date){agendaSelected=date;agendaMonth=date.slice(0,7);render();}
function agendaMoveMonth(delta){const [year,month]=agendaMonth.split('-').map(Number),d=new Date(Date.UTC(year,month-1+delta,1));agendaMonth=d.toISOString().slice(0,7);render();}
function agendaFindNext(){agendaRefresh();const first=agendaAvailableSlots()[0];if(!first){toast('Non ci sono orari disponibili per questo servizio.');return;}agendaSelectDate(first.date);document.getElementById('agenda-day-title')?.scrollIntoView({behavior:'smooth',block:'start'});}
function agendaMonthHTML(){const [y,m]=agendaMonth.split('-').map(Number),first=new Date(Date.UTC(y,m-1,1)),offset=(first.getUTCDay()+6)%7,days=new Date(Date.UTC(y,m,0)).getUTCDate(),today=agendaNow().date;const monthLabel=new Intl.DateTimeFormat('it-IT',{month:'long',year:'numeric',timeZone:'UTC'}).format(first);return `<div class="agenda-month-head"><button class="light" aria-label="Mese precedente" onclick="agendaMoveMonth(-1)">‹</button><h2 aria-live="polite">${monthLabel}</h2><button class="light" aria-label="Mese successivo" onclick="agendaMoveMonth(1)">›</button></div><div class="agenda-weekdays" aria-hidden="true">${['L','M','M','G','V','S','D'].map(d=>`<span>${d}</span>`).join('')}</div><div class="agenda-days">${Array.from({length:offset},()=>'<span></span>').join('')}${Array.from({length:days},(_,i)=>{const date=agendaMonth+'-'+String(i+1).padStart(2,'0'),past=date<today,slots=agendaSlotsFor(date),free=slots.filter(s=>agendaIsFuture(s)&&!agendaReservationFor(agendaData,s.id)).length,booked=slots.some(s=>agendaReservationFor(agendaData,s.id));return `<button class="agenda-date ${date===agendaSelected?'selected':''} ${date===today?'today':''}" aria-pressed="${date===agendaSelected}" aria-label="${agendaDateLabel(date,true)}${free?', '+free+' orari liberi':''}${booked?', appuntamenti presenti':''}" ${past?'disabled':''} onclick="agendaSelectDate('${date}')"><span>${i+1}</span><span class="agenda-date-dot ${free?'free':booked?'booked':''}" aria-hidden="true"></span></button>`;}).join('')}</div><div class="agenda-legend"><span><i></i> Orari disponibili</span><span><i class="booked"></i> Prenotazioni</span></div>`;}
function agendaPage(){agendaRefresh();const coach=role==='coach',slots=agendaSlotsFor(agendaSelected),visible=slots.filter(s=>agendaIsFuture(s)||agendaReservationFor(agendaData,s.id)),free=visible.filter(s=>agendaIsFuture(s)&&!agendaReservationFor(agendaData,s.id)).length;return heading(coach?'Organizza il tuo tempo.':'Scegli quando allenarti.',coach?'Pubblica gli orari disponibili e gestisci le prenotazioni dei tuoi atleti.':'Scegli un giorno e prenota uno degli orari aperti dal preparatore.',action(coach?'+ Aggiungi disponibilità':'Primo orario disponibile',coach?'agendaAvailabilityForm()':'agendaFindNext()'))+`<div class="agenda-role-note"><span class="badge">${coach?'Preparatore · Gestione disponibilità':'Atleta · Prenotazione'}</span><p>${coach?'Tu apri gli orari; gli atleti possono prenotare soltanto gli slot liberi.':'Le schede sono consultabili. Puoi registrare i tuoi allenamenti e prenotare gli orari disponibili.'}</p></div><div class="agenda-layout"><section class="card agenda-calendar"><label class="agenda-filter-label" for="agenda-service">Servizio</label><select id="agenda-service" onchange="agendaFilter=this.value;render()"><option value="">Tutti i servizi</option>${Object.entries(AGENDA_SERVICES).map(([id,s])=>`<option value="${id}" ${agendaFilter===id?'selected':''}>${s.name} · ${s.duration} min</option>`).join('')}</select>${agendaMonthHTML()}</section><section class="card agenda-slots"><div class="sectionhead"><div><p class="eyebrow">${coach?'DISPONIBILITÀ DEL GIORNO':'SCEGLI IL TUO ORARIO'}</p><h2 id="agenda-day-title" tabindex="-1">${agendaDateLabel(agendaSelected)}</h2></div><span class="badge">${free} liberi</span></div><div class="agenda-slot-list">${visible.length?visible.map(s=>{const reservation=agendaReservationFor(agendaData,s.id),booked=!!reservation;return `<article class="agenda-slot ${booked?'is-booked':''}"><div class="agenda-slot-top"><strong>${agendaTime(s.start)} <span>– ${agendaTime(s.start+s.duration)}</span></strong><span class="badge">${booked?'Prenotato':s.duration+' min'}</span></div><h3>${esc(AGENDA_SERVICES[s.service]?.name||s.service)}</h3><p class="small">${esc(s.mode)}</p>${booked?`<p class="agenda-slot-booked">${coach?esc(reservation.athleteName):'Il tuo appuntamento è confermato'}</p>`:coach?`<button class="textbtn" onclick="agendaRemoveSlot('${s.id}')">Rimuovi disponibilità</button>`:`<button onclick="agendaBookForm('${s.id}')" aria-label="Prenota ${agendaTime(s.start)} ${esc(AGENDA_SERVICES[s.service]?.name)}">Prenota questo orario</button>`}</article>`;}).join(''):`<div class="agenda-empty"><span aria-hidden="true">${navIcon('bookings')}</span><h3>Nessun orario disponibile</h3><p class="small">${coach?'Aggiungi una fascia oraria per questo giorno.':'Scegli un giorno con il pallino verde oppure cerca il primo orario libero.'}</p><button class="light" onclick="${coach?'agendaAvailabilityForm()':'agendaFindNext()'}">${coach?'Aggiungi orari':'Cerca disponibilità'}</button></div>`}</div></section></div>${agendaReservationsHTML()}<div class="hint agenda-demo-note">Demo locale · Fuso orario Europe/Rome. Gli orari iniziali sono esempi modificabili dal preparatore. Nessun appuntamento viene inviato a un professionista reale. Account, permessi e disponibilità condivise richiederanno il backend.</div>`;}
function agendaReservationsHTML(){const list=agendaData.reservations.filter(r=>role==='coach'||r.athleteId==='andrea-demo').sort((a,b)=>a.date.localeCompare(b.date)||a.start-b.start);return `<section class="card agenda-reservations"><h2>${role==='coach'?'Appuntamenti degli atleti':'I miei appuntamenti'}</h2><p class="small" style="margin-top:5px">Gli orari scelti sono confermati subito e diventano occupati.</p><div class="list" style="margin-top:18px">${list.length?list.map(r=>`<article class="row"><div class="datebox"><strong>${Number(r.date.slice(8))}</strong><span>${new Intl.DateTimeFormat('it-IT',{month:'short',timeZone:'UTC'}).format(new Date(r.date+'T12:00:00Z'))}</span></div><div class="grow"><span class="badge">${r.status==='confirmed'?'Confermato':'Annullato'}</span><h3 style="margin:7px 0">${esc(AGENDA_SERVICES[r.service]?.name||r.service)}</h3><p class="small">${agendaDateLabel(r.date)} · ${agendaTime(r.start)}–${agendaTime(r.start+r.duration)}</p><p class="small">${esc(r.athleteName)} · ${esc(r.mode)}</p>${r.notes?`<p class="small">${esc(r.notes)}</p>`:''}</div>${r.status==='confirmed'&&agendaIsFuture(r)?`<button class="light" onclick="agendaCancelForm('${r.id}')">Annulla</button>`:''}</article>`).join(''):'<p class="small agenda-no-bookings">Ancora nessun appuntamento. Le nuove prenotazioni compariranno qui.</p>'}</div>${state.bookings.length?`<details class="agenda-legacy"><summary>Richieste salvate nella versione precedente (${state.bookings.length})</summary>${state.bookings.map(b=>`<div class="hint"><strong>${esc(b.service)}</strong><p class="small">${esc(b.date)} · ${esc(b.time)} · ${esc(b.status)}</p></div>`).join('')}<p class="small">Queste richieste non bloccano gli slot del nuovo calendario.</p></details>`:''}</section>`;}
function agendaValidateRange(input,data,now=agendaNow()){
 if(!AGENDA_SERVICES[input.service])return {error:'Scegli un servizio valido.'};
 if(!/^\d{4}-\d{2}-\d{2}$/.test(input.date)||Number.isNaN(Date.parse(input.date+'T12:00:00Z'))||new Date(input.date+'T12:00:00Z').toISOString().slice(0,10)!==input.date)return {error:'Scegli una data valida.'};
 const parse=t=>/^\d{2}:\d{2}$/.test(t)&&Number(t.slice(3))<60?Number(t.slice(0,2))*60+Number(t.slice(3)):NaN,start=parse(input.start),end=parse(input.end),duration=AGENDA_SERVICES[input.service].duration;
 if(!Number.isFinite(start)||!Number.isFinite(end)||start<360||end>1320||end<=start||end-start<duration)return {error:`Imposta una fascia tra le 06:00 e le 22:00 di almeno ${duration} minuti.`};
 if(input.date<now.date||(input.date===now.date&&start<=now.minute))return {error:'Le disponibilità devono iniziare nel futuro.'};
 if(!['In presenza · Studio Forma','Online'].includes(input.mode))return {error:'Scegli una modalità valida.'};
 const slots=[];for(let minute=start;minute+duration<=end;minute+=duration)slots.push({date:input.date,start:minute,duration,service:input.service,mode:input.mode,withdrawn:false});
 if(slots.some(s=>data.slots.some(existing=>!existing.withdrawn&&agendaOverlap(s,existing))))return {error:'La fascia si sovrappone a un orario già presente. Nessun nuovo slot è stato aggiunto.'};
 return {slots,unusedMinutes:end-start-slots.length*duration};
}
function agendaAvailabilityForm(){if(!requireDemoRole('coach'))return;modal('Apri nuove disponibilità',`<form onsubmit="agendaSubmitAvailability(event)"><label for="availability-date">Giorno</label><input id="availability-date" name="date" type="date" min="${agendaNow().date}" value="${agendaSelected<agendaNow().date?agendaNow().date:agendaSelected}" required><label for="availability-service">Servizio e durata di ogni appuntamento</label><select id="availability-service" name="service">${Object.entries(AGENDA_SERVICES).map(([id,s])=>`<option value="${id}">${s.name} · ${s.duration} min</option>`).join('')}</select><div class="fields"><div><label for="availability-start">Dalle</label><input id="availability-start" name="start" type="time" min="06:00" max="22:00" value="09:00" required></div><div><label for="availability-end">Alle</label><input id="availability-end" name="end" type="time" min="06:00" max="22:00" value="12:00" required></div></div><label for="availability-mode">Modalità</label><select id="availability-mode" name="mode"><option>In presenza · Studio Forma</option><option>Online</option></select><div class="hint">La fascia viene divisa in appuntamenti della durata del servizio. Per esempio, dalle 09:00 alle 12:00 con durata 60 minuti vengono creati 3 orari. Eventuali minuti finali insufficienti restano liberi.</div><p class="agenda-form-error" id="availability-error" role="alert"></p><button class="submit">Pubblica orari disponibili</button></form>`);}
function agendaSubmitAvailability(e){e.preventDefault();if(!requireDemoRole('coach'))return;agendaRefresh();const input=Object.fromEntries(new FormData(e.target)),result=agendaValidateRange(input,agendaData);if(result.error){$('#availability-error').textContent=result.error;return;}const next={...agendaData,slots:[...agendaData.slots,...result.slots.map(s=>({...s,id:crypto.randomUUID()}))]};if(!agendaSave(next))return;agendaSelected=input.date;agendaMonth=input.date.slice(0,7);$('#modal').close();render();toast(result.slots.length+(result.slots.length===1?' orario pubblicato nella demo':' orari pubblicati nella demo')+(result.unusedMinutes?' · '+result.unusedMinutes+' min finali esclusi':''));}
function agendaBookForm(slotId){if(!requireDemoRole('athlete'))return;agendaRefresh();const slot=agendaData.slots.find(s=>s.id===slotId);if(!slot||slot.withdrawn||!agendaIsFuture(slot)||agendaReservationFor(agendaData,slotId)){render();toast('Questo orario non è più disponibile.');return;}modal('Conferma il tuo appuntamento',`<form onsubmit="agendaConfirmBooking(event,'${slotId}')"><span class="badge">${slot.duration} minuti · Europe/Rome</span><h3 style="margin:18px 0 8px">${esc(AGENDA_SERVICES[slot.service].name)}</h3><p>${agendaDateLabel(slot.date,true)}<br><strong>${agendaTime(slot.start)}–${agendaTime(slot.start+slot.duration)}</strong><br>${esc(slot.mode)}</p><label for="booking-note">Nota per il preparatore (facoltativa)</label><textarea id="booking-note" name="notes" maxlength="500" placeholder="Es. vorrei rivedere la tecnica dello squat"></textarea><div class="hint">La prenotazione è confermata subito. Potrai annullarla da “I miei appuntamenti”. Si tratta di una prova salvata su questo browser.</div><button class="submit">Conferma prenotazione</button></form>`);}
function agendaConfirmBooking(e,slotId){e.preventDefault();if(!requireDemoRole('athlete'))return;agendaRefresh();const slot=agendaData.slots.find(s=>s.id===slotId);if(!slot||slot.withdrawn||!agendaIsFuture(slot)||agendaReservationFor(agendaData,slotId)){if($('#modal').open)$('#modal').close();render();toast('Orario non più disponibile. Scegline un altro.');return;}const notes=String(new FormData(e.target).get('notes')||'').trim().slice(0,500),reservation={...slot,id:crypto.randomUUID(),slotId,athleteId:'andrea-demo',athleteName:'Andrea Lombardi',notes,status:'confirmed',createdAt:new Date().toISOString()};if(!agendaSave({...agendaData,reservations:[...agendaData.reservations,reservation]}))return;$('#modal').close();render();toast('Appuntamento confermato nella demo');}
function agendaCancelForm(id){agendaRefresh();const r=agendaData.reservations.find(r=>r.id===id);if(!r||r.status!=='confirmed'||!agendaIsFuture(r)||(role!=='coach'&&r.athleteId!=='andrea-demo'))return;modal('Annullare l’appuntamento?',`<p>${esc(AGENDA_SERVICES[r.service].name)}<br>${agendaDateLabel(r.date)} · ${agendaTime(r.start)}</p><div class="hint">${role==='coach'?'L’appuntamento sarà annullato e questo orario verrà chiuso alle prenotazioni.':'L’appuntamento sarà annullato e l’orario tornerà disponibile.'}</div><button class="submit" onclick="agendaConfirmCancellation('${id}')">Conferma annullamento</button>`);}
function agendaConfirmCancellation(id){agendaRefresh();const r=agendaData.reservations.find(r=>r.id===id);if(!r||r.status!=='confirmed'||!agendaIsFuture(r)||(role!=='coach'&&r.athleteId!=='andrea-demo'))return;const next={...agendaData,reservations:agendaData.reservations.map(r=>r.id===id?{...r,status:'cancelled',cancelledBy:role}:r),slots:agendaData.slots.map(s=>s.id===r.slotId&&role==='coach'?{...s,withdrawn:true}:s)};if(!agendaSave(next))return;$('#modal').close();render();toast('Appuntamento annullato');}
function agendaRemoveSlot(id){if(!requireDemoRole('coach'))return;agendaRefresh();const slot=agendaData.slots.find(s=>s.id===id);if(!slot||slot.withdrawn)return;if(agendaReservationFor(agendaData,id)){toast('Annulla prima l’appuntamento associato.');return;}modal('Rimuovere questa disponibilità?',`<p>${agendaDateLabel(slot.date)} · ${agendaTime(slot.start)}–${agendaTime(slot.start+slot.duration)}</p><button class="submit" onclick="agendaConfirmRemoval('${id}')">Rimuovi orario</button>`);}
function agendaConfirmRemoval(id){if(!requireDemoRole('coach'))return;agendaRefresh();if(agendaReservationFor(agendaData,id)){toast('Questo orario è stato prenotato.');return;}if(!agendaSave({...agendaData,slots:agendaData.slots.map(s=>s.id===id?{...s,withdrawn:true}:s)}))return;$('#modal').close();render();toast('Disponibilità rimossa');}
function agendaNextCard(){agendaRefresh();const next=agendaData.reservations.filter(r=>r.status==='confirmed'&&agendaIsFuture(r)&&(role==='coach'||r.athleteId==='andrea-demo')).sort((a,b)=>a.date.localeCompare(b.date)||a.start-b.start)[0];return `<section class="card"><div class="cardhead"><h2>Prossimo appuntamento</h2></div>${next?`<div class="appointment"><div class="datebox"><strong>${Number(next.date.slice(8))}</strong><span>${new Intl.DateTimeFormat('it-IT',{month:'short',timeZone:'UTC'}).format(new Date(next.date+'T12:00:00Z'))}</span></div><div><span class="badge">Confermato</span><h3>${esc(AGENDA_SERVICES[next.service].name)}</h3><p class="small">${agendaDateLabel(next.date)} · ${agendaTime(next.start)}–${agendaTime(next.start+next.duration)}</p></div></div>`:'<p class="small" style="margin:20px 0">Ancora nessun appuntamento. Apri il calendario per scegliere un orario disponibile.</p>'}<div class="apptfoot"><span class="small">${next?esc(next.mode):'Disponibilità aggiornabili dal preparatore'}</span><button class="textbtn" onclick="go('bookings')">Apri agenda →</button></div></section>`;}
window.addEventListener('storage',e=>{if(e.key===AGENDA_KEY){agendaRefresh();if(typeof page!=='undefined'&&(page==='bookings'||page==='home'))render();}});
